using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class VerifyMuckClips {
 public static string Run(){AssetDatabase.Refresh();var paths=AssetDatabase.FindAssets("t:AnimationClip",new[]{"Assets/Research/MuckAnimations"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();int valid=0,curves=0;var report=new System.Collections.Generic.List<string>();foreach(var path in paths){var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);var bindings=AnimationUtility.GetCurveBindings(clip);bool good=clip&&clip.length>0&&!clip.empty&&bindings.Length>0;if(good){valid++;curves+=bindings.Length;}report.Add((good?"VALID":"EMPTY")+" | "+path+" | "+clip.length+"s | curves="+bindings.Length);}System.IO.File.WriteAllLines("D:/67/MuckAnimationResearch/BossAnimations/validation.txt",report);Selection.activeObject=AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("Assets/Research/MuckAnimations");return string.Join("\n",report)+"\nVALID="+valid+" / "+paths.Length+"; curves="+curves;}
}
